CREATE TABLE Facility_Table (
    facility_ID INTEGER PRIMARY KEY,
    facility_location VARCHAR(255),
    facility_name VARCHAR(255)
);

CREATE TABLE Maintenance_Personnel_Table (
    contact_number VARCHAR(255),
    maintenance_personnel_ID INTEGER PRIMARY KEY,
    name VARCHAR(255)
);

CREATE TABLE Facility_Maintenance_Table (
    facility_ID INTEGER NOT NULL,
    maintenance_content VARCHAR(255),
    maintenance_cost FLOAT,
    maintenance_personnel_ID INTEGER NOT NULL,
    maintenance_time DATETIME,
    PRIMARY KEY (maintenance_personnel_ID, facility_ID, maintenance_time),
    FOREIGN KEY (facility_ID) REFERENCES Facility_Table(facility_ID),
    FOREIGN KEY (maintenance_personnel_ID) REFERENCES Maintenance_Personnel_Table(maintenance_personnel_ID)
);
